import{_ as c,a0 as o,w as d,s as p,ao as r,I as t,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT x X-CMD","titleTemplate":false,"description":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210829 Position text on your screen in Linux with ncurses","title":"使用 ncurses 在你的 Linux 屏幕上定位文本","tag":"202109","desc":""},"relativePath":"202109/20210829 Position text on your screen in Linux with ncurses.md","filePath":"[post].md"}'),l={name:"202109/20210829 Position text on your screen in Linux with ncurses.md"};function u(h,s,g,k,b,m){const n=o("Link");return d(),p("div",null,[s[15]||(s[15]=r(`<h1 id="使用-ncurses-在你的-linux-屏幕上定位文本" tabindex="-1">使用 ncurses 在你的 Linux 屏幕上定位文本 <a class="header-anchor" href="#使用-ncurses-在你的-linux-屏幕上定位文本" aria-label="Permalink to “使用 ncurses 在你的 Linux 屏幕上定位文本”">​</a></h1><blockquote><p>使用 ncurses 在 Linux 屏幕上的特定位置放置文本，可以带来更友好的用户界面体验。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202109/06/085908qrdrrv5dru6pcucr.jpg" alt=""></p><p>大多数的 Linux 实用程序仅仅只在屏幕的底部滚动文本。如果你想在屏幕中放置你的文本，例如一个游戏或者一个数据展示，你可以试试 ncurses。</p><p>curses 是一个旧的 Unix 库，它可以在文本终端界面控制光标。curses 的名称就来自于术语 “<ruby>光标控制<rt>cursor control</rt></ruby>”。多年以后，其他人编写了新的 curses 版本用来添加新的功能，新版本被叫做 “new curses” 或者 “ncurses”。你可以在每个流行的 Linux 发行版中找到 ncurses。尽管默认情况下可能未安装开发库、头文件和文档。例如，在 Fedora 上，你需要使用以下命令安装 <code>ncurses-devel</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ncurses-devel</span></span></code></pre></div><h3 id="在程序中使用-ncurses" tabindex="-1">在程序中使用 ncurses <a class="header-anchor" href="#在程序中使用-ncurses" aria-label="Permalink to “在程序中使用 ncurses”">​</a></h3><p>要在屏幕上直接寻址，你首先需要初始化 <code>ncurses</code> 库。大部分程序会通过以下三行来做到这一点：</p><ul><li><code>initscr()</code>：初始化窗口对象和 ncurses 代码，返回代表整个屏幕的窗口对象</li><li><code>cbreak()</code>：禁用缓冲并使键入的输入立即可用</li><li><code>noecho()</code>：关闭回显，因此用户输入不会显示在屏幕上</li></ul><p>这些函数定义在 <code>curses.h</code> 头文件中，你需要在你的程序中通过以下方式将其包含进来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;curses.h&gt;</span></span></code></pre></div><p>初始化终端后，你可以自由使用任何 ncurses 函数，我们将在示例程序中探讨其中的一些函数。</p><p>当你使用完 ncurses 并想返回到常规终端模式下时，使用 <code>endwin()</code> 重置一切。此命令可以重置任何屏幕颜色，将光标移动到屏幕的左下角，并使光标可见。通常在退出程序之前执行此操作。</p><h3 id="在屏幕上寻址" tabindex="-1">在屏幕上寻址 <a class="header-anchor" href="#在屏幕上寻址" aria-label="Permalink to “在屏幕上寻址”">​</a></h3><p>关于 ncurses 首先需要知道的是屏幕的坐标分为行和列，左上角的是 <code>0,0</code> 点。ncurses 定义了两个全局变量来帮助你识别屏幕：<code>LINES</code> 是屏幕的行数，<code>COLS</code> 是屏幕的列数。屏幕右下角的位置是 <code>LINES-1,COLS-1</code>。</p><p>例如，如果你想要移动光标到第 10 行和第 30 列，你可以使用 <code>move()</code> 函数，移动到此坐标：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>move(10, 30);</span></span></code></pre></div><p>之后显示的任何文本都将从屏幕的该位置开始。要显示单个字符，请对单个字符使用 <code>addch(c)</code> 函数。要显示字符串，将对字符串使用 <code>addstr(s)</code> 函数。对于类似于 <code>printf</code> 的格式化输出，请使用带有常用选项的 <code>printw(fmt, ...)</code>。</p><p>移动到屏幕指定位置和显示文本是一件很常见的事情，ncurses 提供了同时执行这两项操作的快捷方式。<code>mvaddch(row, col, c)</code> 函数将在屏幕第 <code>row</code> 行，第 <code>col</code> 列的位置显示一个字符。而 <code>mvaddstr(row, col, s)</code> 函数将在屏幕第 <code>row</code> 行，第 <code>col</code> 列的位置显示一个字符串。举个更直接的例子，在程序中使用 <code>mvaddstr(10, 30, &quot;Welcome to ncurses&quot;);</code> 函数将从屏幕的第 <code>10</code> 行和第 <code>30</code> 列开始显示文本 <code>Welcome to ncurses</code>。使用 <code>mvaddch(0, 0, &#39;+&#39;)</code> 函数将在屏幕的左上角第 <code>0</code> 行和第 <code>0</code> 列处显示一个加号（<code>+</code>）。</p><p>在终端屏幕上绘制文本会对某些系统产生性能影响，尤其是在较旧的硬件终端上。因此 ncurses 允许你“堆叠”一堆文本以显示在屏幕上，然后使用 <code>refresh()</code> 函数使所有这些更改对用户可见。</p><p>让我们来看一个将以上所有内容整合在一起的简单示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;curses.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int</span></span>
<span class="line"><span>main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  initscr();</span></span>
<span class="line"><span>  cbreak();</span></span>
<span class="line"><span>  noecho();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  mvaddch(0, 0, &#39;+&#39;);</span></span>
<span class="line"><span>  mvaddch(LINES - 1, 0, &#39;-&#39;);</span></span>
<span class="line"><span>  mvaddstr(10, 30, &quot;press any key to quit&quot;);</span></span>
<span class="line"><span>  refresh();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  getch();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  endwin();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>程序的开始初始化了一个终端窗口，然后在屏幕的左上角打印了一个加号，在左下角打印了一个减号，在第 <code>10</code> 行和第 <code>30</code> 列打印了 <code>press any key to quit</code> 文本。程序通过使用 <code>getch()</code> 函数接收了键盘输入的单个字符，接着，使用 <code>endwin()</code> 函数在程序完全退出前重置了终端。</p><p><code>getch()</code> 是一个很有用的函数，你可以使用它来做很多事情。我经常使用它在我退出程序前用来暂停。与大多数 ncurses 函数一样，还有一个名为 <code>mvgetch(row, col)</code> 的 <code>getch()</code> 版本，用于在等待字符输入之前移动到屏幕位置的第 <code>row</code> 行，第 <code>col</code> 列。</p><h3 id="使用-ncurses-编译" tabindex="-1">使用 ncurses 编译 <a class="header-anchor" href="#使用-ncurses-编译" aria-label="Permalink to “使用 ncurses 编译”">​</a></h3><p>如果你尝试以通常的方式编译该示例程序，例如 <code>gcc pause.c</code>，你可能会从链接器中获得大量错误列表。那是因为 GNU C 编译器不会自动链接 <code>ncurses</code> 库。相反，你需要使用 <code>-l ncurses</code> 命令行选项加载它以进行链接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -o pause pause.c -lncurses</span></span></code></pre></div><p>运行新程序将打印一条简单的 <code>press any key to quit</code>消息，该消息差不多位于屏幕中央：</p><p><img src="https://opensource.com/sites/default/files/press-key_0.png" alt="centered message in a program window"></p><p><em>图 1：程序中居中的 “press any key to quit” 消息。</em></p><h3 id="使用-ncurses-构建更好的程序" tabindex="-1">使用 ncurses 构建更好的程序 <a class="header-anchor" href="#使用-ncurses-构建更好的程序" aria-label="Permalink to “使用 ncurses 构建更好的程序”">​</a></h3><p>探索 <code>ncurses</code> 库函数以了解在屏幕上显示文本的其它方法。你可以在 <code>ncurses</code> 的手册页中找到所有 <code>ncurses</code> 函数的列表。这给出了 ncurses 的一般概述，并提供了不同 <code>ncurses</code> 函数的类似表格的列表，并参考了包含完整详细信息的手册页。例如，在 <code>curs_printw(3X)</code> 手册页中描述了 <code>printw</code>，可以通过以下方式查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man 3x curs_printw</span></span></code></pre></div><p>更简单点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man curs_printw</span></span></code></pre></div><p>使用 ncurses，你可以创建更多有趣的程序。通过在屏幕上的特定位置打印文本，你可以创建在终端中运行的游戏和高级实用程序。</p><hr>`,37)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/21/8/ncurses-linux"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/8/ncurses-linux",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[e("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(n,{href:"https://github.com/perfiffer"},{default:i(()=>[...s[4]||(s[4]=[e("perfiffer",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=c(l,[["render",u]]);export{y as __pageData,C as default};
